package io.github.eslamasabry.oc.core.data.android

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import io.github.eslamasabry.oc.core.data.secret.Aead
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM with a non-exportable Android Keystore key (plan 05 §4.1): `PURPOSE_ENCRYPT or PURPOSE_DECRYPT`, GCM, no
 * padding, no user authentication (workers read secrets), no StrongBox. The IV is generated by Keystore.
 * Calls are serialised by `AeadSecretStore`, so the key is created at most once.
 */
internal class KeystoreAead(private val alias: String) : Aead {

    override fun seal(plaintext: ByteArray, aad: ByteArray): Aead.Sealed {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, key())
        cipher.updateAAD(aad)
        val body = cipher.doFinal(plaintext)
        return Aead.Sealed(cipher.iv, body)
    }

    override fun open(iv: ByteArray, ciphertextAndTag: ByteArray, aad: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.DECRYPT_MODE, existingKey() ?: throw KeyMissing(), GCMParameterSpec(TAG_BITS, iv))
        cipher.updateAAD(aad)
        return cipher.doFinal(ciphertextAndTag)
    }

    private fun existingKey(): SecretKey? {
        val store = KeyStore.getInstance(PROVIDER).apply { load(null) }
        return store.getKey(alias, null) as? SecretKey
    }

    private fun key(): SecretKey = existingKey() ?: generate()

    private fun generate(): SecretKey {
        val spec = KeyGenParameterSpec.Builder(alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(KEY_BITS)
            .setRandomizedEncryptionRequired(true)
            .build()
        return KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, PROVIDER).run {
            init(spec)
            generateKey()
        }
    }

    /** The Keystore lost the key (app data cleared, device restore): every entry is unreadable, never guessed. */
    class KeyMissing : Exception()

    private companion object {
        const val PROVIDER = "AndroidKeyStore"
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val TAG_BITS = 128
        const val KEY_BITS = 256
    }
}
